#!/usr/bin/env python3
"""
Proof-of-Concept: Missing Host Key Verification in SSH (RFC 4251)

This script demonstrates the vulnerability where a client accepts an arbitrary 
host key without verifying it against a known trusted fingerprint. This allows 
a man-in-the-middle attacker to intercept and decrypt traffic.

WARNING: Educational purposes only. Do not use on networks you do not own.
"""

import socket
import struct
import hashlib
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.primitives import serialization, hashes

def generate_mock_host_key():
    """Generates a temporary RSA host key for demonstration."""
    private_key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=2048,
    )
    return private_key

def get_host_key_fingerprint(public_key):
    """Calculates the SHA-256 fingerprint of a public key (RFC 4251 style)."""
    pub_bytes = public_key.public_bytes(
        encoding=serialization.Encoding.OpenSSH,
        format=serialization.PublicFormat.OpenSSH
    )
    # Strip 'ssh-rsa' prefix for hashing as per common practice
    key_data = bytes.fromhex(pub_bytes.decode().split()[1])
    digest = hashlib.sha256(key_data).hexdigest()
    return ':'.join(digest[i:i+2] for i in range(0, len(digest), 2))

class VulnerableSSHClient:
    """
    Simulates an SSH client with host key verification disabled.
    This mimics the behavior described in RFC 4251 Section 4.1 where
    implementations MAY provide an option not to accept host keys that cannot be verified.
    """
    
    def __init__(self, verify_host_key=False):
        self.verify_host_key = verify_host_key
        self.trusted_fingerprints = set()
        
    def connect_and_verify(self, server_public_key, expected_fingerprint=None):
        """
        Simulates the key exchange verification step.
        In a vulnerable implementation (verify_host_key=False), this always returns True.
        """
        current_fp = get_host_key_fingerprint(server_public_key)
        
        print(f"[Client] Received host key fingerprint: {current_fp}")
        
        if self.verify_host_key:
            # Secure behavior: Check against known trusted keys
            if expected_fingerprint and current_fp != expected_fingerprint:
                raise SecurityError(
                    f"Host key mismatch! Expected {expected_fingerprint}, got {current_fp}. "
                    "Connection aborted."
                )
            print("[Client] Host key verified successfully.")
        else:
            # Vulnerable behavior: Blindly accept any key
            print("[Client] WARNING: Host key verification is DISABLED.")
            print(f"[Client] Accepting unverified host key: {current_fp}")
            return True
        
        return True

class SecurityError(Exception):
    pass

def demonstrate_vulnerability():
    """
    Demonstrates the MITM scenario where an attacker presents a fake key.
    """
    print("="*60)
    print("POC: Missing Host Key Verification (RFC 4251 Section 4.1 & 9.3.4)")
    print("="*60)
    
    # 1. Legitimate Server Setup
    legit_key = generate_mock_host_key()
    legit_public = legit_key.public_key()
    legit_fp = get_host_key_fingerprint(legit_public)
    print(f"\n[Server] Legitimate host key fingerprint: {legit_fp}")
    
    # 2. Attacker Setup
    attacker_key = generate_mock_host_key()
    attacker_public = attacker_key.public_key()
    attacker_fp = get_host_key_fingerprint(attacker_public)
    print(f"[Attacker] Generated fake host key fingerprint: {attacker_fp}")
    
    # 3. Vulnerable Client Connection
    print("\n--- Scenario A: Client with Host Key Verification DISABLED ---")
    vulnerable_client = VulnerableSSHClient(verify_host_key=False)
    try:
        # The attacker presents their key instead of the legitimate server's key
        vulnerable_client.connect_and_verify(attacker_public, expected_fingerprint=legit_fp)
        print("[Result] VULNERABLE: Client accepted attacker's key. MITM successful.")
        print("[Impact] Attacker can now decrypt and manipulate all traffic.")
    except SecurityError as e:
        print(f"[Result] SECURE: {e}")
        
    # 4. Secure Client Connection (for comparison)
    print("\n--- Scenario B: Client with Host Key Verification ENABLED ---")
    secure_client = VulnerableSSHClient(verify_host_key=True)
    try:
        # The attacker presents their key, but client checks against legitimate fingerprint
        secure_client.connect_and_verify(attacker_public, expected_fingerprint=legit_fp)
        print("[Result] VULNERABLE: Client accepted attacker's key.")
    except SecurityError as e:
        print(f"[Result] SECURE: Connection rejected. {e}")

if __name__ == "__main__":
    demonstrate_vulnerability()